#!/usr/bin/env python3
"""Generate ui/Grassfield/Ui/Tokens.qml, the compositor plugin's token header and the Settings portal backend's accent
palette, from ui/tokens/tokens.json (stdlib only).

Usage: gen-tokens.py [--check]
  --check  do not write; exit 1 if a generated file is stale.

The compositor plugin draws with its own renderer: the groups in PLUGIN_GROUPS are also written as C++ constants to
compositor/src/core/ThemeTokens.hpp (numbers, and colours as 0xRRGGBB), read by compositor/src/core/Theme.hpp (ADR-0003:
one source of values for both renderers; ADR-0015).
The Settings portal backend (ADR-0035 D-8) publishes the accent colour to other toolkits: the accents of
ui/Grassfield/Ui/Accent.js (multicolor = the palettes' own `accent`, then `color.accentLight` / `color.accentDark`) are
written to apps/portal-settings/src/PaletteTokens.hpp.
"""
import json
import pathlib
import re
import sys

UI = pathlib.Path(__file__).resolve().parent.parent
SRC = UI / "tokens" / "tokens.json"
DST = UI / "Grassfield" / "Ui" / "Tokens.qml"
PLUGIN_DST = UI.parent / "compositor" / "src" / "core" / "ThemeTokens.hpp"
PLUGIN_GROUPS = ("titlebar", "window", "tiling")  # window: the lights the apps draw (ADR-0015 P7); tiling: ADR-0036
PORTAL_DST = UI.parent / "apps" / "portal-settings" / "src" / "PaletteTokens.hpp"


def is_leaf(node):
    return isinstance(node, dict) and "value" in node


def qml_literal(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return repr(value)
    return json.dumps(value)


def qml_type(value):
    if isinstance(value, bool):
        return "bool"
    if isinstance(value, int):
        return "int"
    if isinstance(value, float):
        return "real"
    if isinstance(value, str):
        return "string"
    return "var"


def camel(*parts):
    first, *rest = parts
    return first + "".join(p[:1].upper() + p[1:] for p in rest)


def generate(data):
    out = [
        "pragma Singleton",
        "// GENERATED by ui/tools/gen-tokens.py from ui/tokens/tokens.json. Do not edit.",
        "import QtQml",
        "",
        "QtObject {",
        f"    readonly property int version: {data['version']}",
    ]
    for group, body in data.items():
        if group in ("version", "_note"):
            continue
        if group == "color":
            for appearance, roles in body.items():
                out.append("")
                out.append(f"    // color roles, {appearance} appearance")
                out.append(f"    readonly property var {camel('color', appearance)}: ({{")
                items = list(roles.items())
                for i, (role, leaf) in enumerate(items):
                    comma = "," if i < len(items) - 1 else ""
                    out.append(f"        {role}: {qml_literal(leaf['value'])}{comma}  // {leaf['source']}")
                out.append("    })")
            continue
        out.append("")
        for name, leaf in body.items():
            if not is_leaf(leaf):
                raise SystemExit(f"tokens.json: {group}.{name} is not a {{value, source}} leaf")
            v = leaf["value"]
            expr = qml_literal(v)
            typ = qml_type(v)
            # Optional leaf keys make a token follow an Appearance setting (Settings > Accessibility > Display):
            #   "textScale": true        the size is scaled by Appearance.textScale and rounded (Text Size)
            #   "increaseContrast": V    the value is V while Appearance.increaseContrast is on (Increase Contrast)
            if leaf.get("textScale"):
                expr = f"Math.round({expr} * Appearance.textScale)"
                typ = "int"
            if "increaseContrast" in leaf:
                expr = f"Appearance.increaseContrast ? {qml_literal(leaf['increaseContrast'])} : {expr}"
            out.append(f"    // {leaf['source']}")
            out.append(f"    readonly property {typ} {camel(group, name)}: {expr}")
    out.append("}")
    return "\n".join(out) + "\n"


def cpp_constant(group, name, value):
    """One C++ constant of a plugin token: kGroupName, int / double / 0xRRGGBB colour, a list of equal-length integer lists
    (the tiling zones, `int k[][N]`) or a list of strings (`std::string_view k[]`)."""
    ident = "k" + camel(group, name)[:1].upper() + camel(group, name)[1:]
    if isinstance(value, list) and value and all(isinstance(row, list) and row and all(type(n) is int for n in row) for row in value):
        width = len(value[0])
        if any(len(row) != width for row in value):
            raise SystemExit(f"tokens.json: {group}.{name}: the integer lists of a plugin token have one length")
        rows = ", ".join("{" + ", ".join(str(n) for n in row) + "}" for row in value)
        return f"inline constexpr int {ident}[][{width}] = {{{rows}}};"
    if isinstance(value, list) and value and all(isinstance(text, str) and re.fullmatch(r"[a-z0-9-]+", text) for text in value):
        items = ", ".join(json.dumps(text) for text in value)
        return f"inline constexpr std::string_view {ident}[] = {{{items}}};"
    if isinstance(value, bool):
        return f"inline constexpr bool {ident} = {'true' if value else 'false'};"
    if isinstance(value, int):
        return f"inline constexpr int {ident} = {value};"
    if isinstance(value, float):
        return f"inline constexpr double {ident} = {value!r};"
    if isinstance(value, str) and re.fullmatch(r"#[0-9A-Fa-f]{6}", value):
        return f"inline constexpr uint32_t {ident} = 0x{value[1:].upper()};"
    raise SystemExit(f"tokens.json: {group}.{name}: a plugin token is a number, a #rrggbb colour, a list of integer lists or a list of ids")


def generate_plugin(data):
    out = [
        "#pragma once",
        "",
        "// GENERATED by ui/tools/gen-tokens.py from ui/tokens/tokens.json. Do not edit.",
        "// The design tokens the compositor plugin draws with (read by core/Theme.hpp; no Hyprland include).",
        "",
        "#include <cstdint>",
        "#include <string_view>",
        "",
        "namespace gf::theme::tokens {",
    ]
    for group in PLUGIN_GROUPS:
        body = data.get(group)
        if not isinstance(body, dict):
            raise SystemExit(f"tokens.json: plugin group {group} is missing")
        for name, leaf in body.items():
            if not is_leaf(leaf):
                raise SystemExit(f"tokens.json: {group}.{name} is not a {{value, source}} leaf")
            out.append(f"    // {leaf['source']}")
            out.append(f"    {cpp_constant(group, name, leaf['value'])}")
    out.append("} // namespace gf::theme::tokens")
    return "\n".join(out) + "\n"


def accent_names(data):
    """The accent names in Accent.js order: multicolor, then the roles of color.accentLight without a "Text" suffix."""
    light = data["color"]["accentLight"]
    dark = data["color"]["accentDark"]
    names = [n for n in light if not n.endswith("Text")]
    if [n for n in dark if not n.endswith("Text")] != names:
        raise SystemExit("tokens.json: color.accentLight and color.accentDark name different accents")
    return ["multicolor"] + names


def generate_portal(data):
    color = data["color"]
    rows = []
    for name in accent_names(data):
        if name == "multicolor":
            light, dark = color["light"]["accent"], color["dark"]["accent"]
        else:
            light, dark = color["accentLight"][name], color["accentDark"][name]
        for leaf in (light, dark):
            if not re.fullmatch(r"#[0-9A-Fa-f]{6}", str(leaf["value"])):
                raise SystemExit(f"tokens.json: accent {name}: a portal accent is a #rrggbb colour")
        rows.append(f'    {{"{name}", 0x{light["value"][1:].upper()}, 0x{dark["value"][1:].upper()}}},  // {light["source"]}')
    out = [
        "#pragma once",
        "",
        "// GENERATED by ui/tools/gen-tokens.py from ui/tokens/tokens.json. Do not edit.",
        "// The accent colours the Settings portal backend publishes (ADR-0035 D-8): name, light and dark appearance, 0xRRGGBB.",
        "",
        "#include <cstdint>",
        "",
        "namespace grassfield::portal::tokens {",
        "",
        "struct Accent {",
        "    const char *name;",
        "    uint32_t light;",
        "    uint32_t dark;",
        "};",
        "",
        "inline constexpr Accent kAccents[] = {",
        *rows,
        "};",
        "",
        "} // namespace grassfield::portal::tokens",
    ]
    return "\n".join(out) + "\n"


# Provenance (audit GF-095): every token says where its value comes from, with a pointer a reviewer can follow: the F1
# reference analysis, a spec, an ADR, a test, the master prompt or an audit. A bare "estimate" is not a source.
REPO = UI.parent
F1 = REPO / "docs" / "testing" / "f1-reference-gaps.md"
PATH_CITE = re.compile(r"(?<![\w./-])(?:docs|tests)/[A-Za-z0-9_./-]+\.(?:md|py|qml|sh|json)")
ADR_CITE = re.compile(r"ADR-(\d{4})")
# Provenance kept in the maintainers' private repository (design audits, the master prompt). A source may cite them; where the
# file is not in this checkout (the public repository) the pointer is accepted, not followed, and main() says so once.
PRIVATE_PATHS = ("docs/audits/", "docs/master-prompt.md", "docs/STATE.md")
private_skipped = set()


def is_private(path):
    return path.startswith(PRIVATE_PATHS)
# A section pointer has one form: `<file> \u00a7 <section>` (docs/**.md or master-prompt), ended by ";" or "]".
SECTION_START = re.compile(r"(?<![\w./-])(docs/[A-Za-z0-9_./-]+\.md|master-prompt) \u00a7 (?=\S)")  # anchored path, one plain space, then text


def section_cites(source):
    """(file, section text) of every `<file> \u00a7 <section>` of a source. A section ends at ";", "[", "]" or where the next pointer starts."""
    starts = list(SECTION_START.finditer(source))
    cites = []
    for i, m in enumerate(starts):
        end = len(source)
        for stop in (";", "[", "]"):
            at = source.find(stop, m.end())
            if at >= 0:
                end = min(end, at)
        if i + 1 < len(starts):
            end = min(end, starts[i + 1].start())
        cites.append((m.group(1), source[m.end():end]))
    return cites
# `ADR-0016 section 5`: the number of a numbered heading of that ADR.
ADR_SECTION_CITE = re.compile(r"ADR-(\d{4}) section (\d+(?:\.\d+)?)")


def headings_of(path):
    """Heading names (## and ###) of a markdown file, lower-case, the parenthetical tail dropped, and their numbers ('5.5')."""
    names, numbers = [], set()
    for line in path.read_text().splitlines():
        m = re.match(r"#{1,4} (.+)", line)
        if not m:
            continue
        text = m.group(1).strip()
        number = re.match(r"(\d+(?:\.\d+)?)\.?(?:\s|$)", text)
        if number:
            numbers.add(number.group(1))
        names.append(re.sub(r"\s*\(.*$", "", text).strip().lower())
    return names, numbers


def f1_headings():
    return headings_of(F1)[0]


def section_resolves(text, headings):
    """'Window chrome, Dock and Menus and popovers' must be made of real headings (longest first), joined by ', ' or ' and '."""
    rest = re.sub(r"\s*\(.*?\)", "", text).strip().lower()
    by_length = sorted(headings, key=len, reverse=True)
    while rest:
        for name in by_length:
            if not rest.startswith(name):
                continue
            tail = rest[len(name):]
            if tail == "":
                rest = ""
                break
            separator = re.match(r"^(?:,\s*| and )", tail)
            if separator:  # a name is followed by a separator or nothing: not by more letters ("Menu barDock")
                rest = tail[separator.end():]
                break
        else:
            return False
    return True


def source_problems(source, headings):
    """Why a token source is not a followable pointer (empty list: it is)."""
    problems = []
    cited = False
    for path in PATH_CITE.findall(source):
        cited = True
        if not (REPO / path).exists():
            if is_private(path):
                private_skipped.add(path)
                continue
            problems.append("cites %s, which does not exist" % path)
    for number in ADR_CITE.findall(source):
        cited = True
        if not list((REPO / "docs" / "decisions").glob("ADR-%s*" % number)):
            problems.append("cites ADR-%s, which does not exist" % number)
    for number, section in ADR_SECTION_CITE.findall(source):
        files = list((REPO / "docs" / "decisions").glob("ADR-%s*" % number))
        if files and section not in headings_of(files[0])[1]:
            problems.append("cites section %s of ADR-%s, which has no such numbered heading" % (section, number))
    for path, section in section_cites(source):
        cited = True
        while section.count(")") > section.count("("):  # the ")" that closes a sentence around the pointer
            section = section[:section.rindex(")")]
        section = section.strip()
        target = REPO / ("docs/master-prompt.md" if path == "master-prompt" else path)
        if not target.exists():
            if is_private(str(target.relative_to(REPO))):
                private_skipped.add(str(target.relative_to(REPO)))
            continue  # reported above as a missing path
        names, numbers = headings_of(target)
        if path.endswith("f1-reference-gaps.md"):
            ok = section_resolves(section, names)
        elif path == "master-prompt":
            # `5.5`, then end or a separator: not `5.5.9`, not `5.5x`.
            lead = re.match(r"(\d+(?:\.\d+)?)(?:$|[\s:;,)\]])", section)
            ok = bool(lead) and lead.group(1) in numbers
        else:
            ok = section.lower() in names  # the whole heading, not a prefix of it
        if not ok:
            problems.append("cites '%s \u00a7 %s', which is not a heading of that file" % (path, section))
    # Any section sign must belong to a well-formed `<file> \u00a7 <section>` pointer (one plain space each side of the sign, a
    # full docs path or master-prompt): `ui.md \u00a7Nope`, `master-prompt \u00a79.9` and a no-break space do not slip through
    # because the source also holds another valid pointer. `master-prompt section 9.9` is the wrong form for the master prompt.
    well_formed = {m.end() - 2 for m in SECTION_START.finditer(source)}
    for at, ch in enumerate(source):
        if ch == "\u00a7" and at not in well_formed:
            problems.append("has a section sign that is not part of a `<docs path or master-prompt> \u00a7 <section>` pointer (near '%s')" % source[max(0, at - 24):at + 24].replace("\u00a0", "<nbsp>"))
    if re.search(r"master-prompt\s+(?:section|sec\b)", source):
        problems.append("cites the master prompt as `section`: write `master-prompt \u00a7 <n.n>`")
    # A declared estimate: no reference covers the value, and the source says what it is and why ("estimate: a pressed light
    # darkens by this much": a role, not a bare word). A bare "estimate" is still not a source.
    declared_estimate = re.match(r"estimate: \S+(?:\s+\S+){3,}", source) is not None
    if not cited and not declared_estimate:
        problems.append("has no pointer (f1-reference-gaps section, spec, ADR or test) and is not a declared estimate with a reason")
    return problems


def provenance_errors(data):
    headings = f1_headings()
    errors = []

    def walk(node, path):
        if is_leaf(node):
            # No group is exempt, the plugin groups included (their sources are copied into the generated header).
            for problem in source_problems(str(node.get("source", "")), headings):
                errors.append(".".join(path) + " " + problem)
            return
        if isinstance(node, dict):
            for key, child in node.items():
                if not key.startswith("_") and isinstance(child, dict):
                    walk(child, path + [key])

    walk(data, [])
    return errors


def main():
    data = json.loads(SRC.read_text())
    unsourced = provenance_errors(data)
    if private_skipped:
        print("gen-tokens: note: %d cited private provenance file(s) are not in this checkout (public repository); those pointers are not followed" % len(private_skipped), file=sys.stderr)
    if unsourced:
        print("gen-tokens: token sources that are not followable pointers:\n  " + "\n  ".join(unsourced), file=sys.stderr)
        return 1
    outputs = ((DST, generate(data), "ui/Grassfield/Ui/Tokens.qml"), (PLUGIN_DST, generate_plugin(data), "compositor/src/core/ThemeTokens.hpp"),
               (PORTAL_DST, generate_portal(data), "apps/portal-settings/src/PaletteTokens.hpp"))
    if "--check" in sys.argv[1:]:
        stale = [label for path, text, label in outputs if not path.exists() or path.read_text() != text]
        for label in stale:
            print(f"gen-tokens: {label} is stale; run ui/tools/gen-tokens.py", file=sys.stderr)
        if stale:
            return 1
        print("gen-tokens: up to date")
        return 0
    for path, text, label in outputs:
        path.write_text(text)
        print(f"gen-tokens: wrote {label}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
